import {
  Children,
  cloneElement,
  type InputHTMLAttributes,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  type TextareaHTMLAttributes,
  useId,
} from "react";
import { cx } from "../utils/cx";

export type FieldProps = {
  label: ReactNode;
  /** Help under the control. */
  hint?: ReactNode;
  /** Validation message; marks the control aria-invalid and announces it. */
  error?: ReactNode;
  /** Visually hide the label (it is still the accessible name). */
  hideLabel?: boolean;
  /** Control id; generated when omitted. */
  id?: string;
  className?: string;
  /** Exactly one control (Input, Select, Textarea...). */
  children: ReactElement;
};

/**
 * Label, control, hint and error, wired together (id, aria-describedby, aria-invalid). Server-compatible: it clones
 * its one control rather than using context.
 */
export function Field({ label, hint, error, hideLabel, id, className, children }: FieldProps) {
  const auto = useId();
  const controlId = id ?? `hm${auto.replace(/:/g, "")}`;
  const hintId = hint ? `${controlId}-hint` : undefined;
  const errorId = error ? `${controlId}-error` : undefined;
  const child = Children.only(children);
  const childProps = (isValidElement(child) ? child.props : {}) as Record<string, unknown>;
  const describedBy = cx(childProps["aria-describedby"] as string | undefined, hintId, errorId) || undefined;
  return (
    <div className={cx("hm-field", className)} data-invalid={error ? "" : undefined}>
      <label className={cx("hm-field-label", hideLabel && "hm-sr-only")} htmlFor={controlId}>
        {label}
      </label>
      {cloneElement(child as ReactElement<Record<string, unknown>>, {
        id: controlId,
        "aria-describedby": describedBy,
        "aria-invalid": error ? true : childProps["aria-invalid"],
      })}
      {hint ? (
        <p id={hintId} className="hm-field-hint">
          {hint}
        </p>
      ) : null}
      {error ? (
        <p id={errorId} className="hm-field-error" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

export function Input({ className, ...rest }: InputHTMLAttributes<HTMLInputElement> & { ref?: Ref<HTMLInputElement> }) {
  return <input {...rest} className={cx("hm-control hm-input", className)} />;
}

export function Textarea({
  autoGrow,
  className,
  ...rest
}: TextareaHTMLAttributes<HTMLTextAreaElement> & {
  ref?: Ref<HTMLTextAreaElement>;
  /** Grow with the content (CSS `field-sizing`; browsers without it keep a fixed, resizable box). */
  autoGrow?: boolean;
}) {
  return (
    <textarea {...rest} className={cx("hm-control hm-textarea", className)} data-autogrow={autoGrow ? "" : undefined} />
  );
}

export type CheckboxProps = Omit<InputHTMLAttributes<HTMLInputElement>, "type"> & {
  label: ReactNode;
  /** `switch` renders a toggle (role="switch") for settings that apply at once. */
  appearance?: "checkbox" | "switch";
  /** Visually hide the label (it is still the accessible name), as in a settings row that already shows it. */
  hideLabel?: boolean;
  ref?: Ref<HTMLInputElement>;
};

/** Native checkbox with its label; `appearance="switch"` for immediate settings. */
export function Checkbox({ label, appearance = "checkbox", hideLabel, className, ...rest }: CheckboxProps) {
  return (
    <label className={cx("hm-check", className)} data-appearance={appearance}>
      <input
        {...rest}
        type="checkbox"
        role={appearance === "switch" ? "switch" : undefined}
        className="hm-check-input"
      />
      <span className={cx("hm-check-label", hideLabel && "hm-sr-only")}>{label}</span>
    </label>
  );
}
